/**
 * An error crossing to the app.
 *
 * `code` is the Rust path of the underlying variant, such as
 * `OpError::NotFound` or `TcpError::Timeout`. The app maps it to words
 * through the table generated from `design/errors.json`. `detail` carries a
 * value the words may need, such as a file name, and is optional.
 */
sealed class FerryException: kotlin.Exception() {
    
    /**
     * The only variant. A code and an optional detail.
     */
    class Failed(
        
        /**
         * The Rust path of the variant, used as the lookup key.
         */
        val `code`: kotlin.String, 
        
        /**
         * A value the message may need. Never a sentence.
         */
        val `detail`: kotlin.String?
        ) : FerryException() {
        override val message
            get() = "code=${ `code` }, detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FerryException> {
        override fun lift(error_buf: RustBuffer.ByValue): FerryException = FfiConverterTypeFerryError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFerryError : FfiConverterRustBuffer<FerryException> {
    override fun read(buf: ByteBuffer): FerryException {
        

        return when(buf.getInt()) {
            1 -> FerryException.Failed(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FerryException): ULong {
        return when(value) {
            is FerryException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterOptionalString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: FerryException, buf: ByteBuffer) {
        when(value) {
            is FerryException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterOptionalString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



