/**
 * Where pairing is.
 */
sealed class PairingState {
    
    /**
     * Not pairing.
     */
    object Idle : PairingState()
    
    
    /**
     * Looking for a device, or on the phone, waiting for a Mac. Code
     * method.
     */
    data class Waiting(
        /**
         * When this pairing attempt gives up.
         */
        val `expiresUnixSecs`: kotlin.Long) : PairingState()
        
    {
        

        companion object
    }
    
    /**
     * The Mac has candidates to pick from. Code method.
     */
    data class Found(
        /**
         * What can be picked.
         */
        val `candidates`: List<uniffi.ferry_runtime.PairingCandidate>, 
        /**
         * When this pairing attempt gives up.
         */
        val `expiresUnixSecs`: kotlin.Long) : PairingState()
        
    {
        

        companion object
    }
    
    /**
     * Both screens show the code. Code method.
     */
    data class Code(
        /**
         * Six digits, zero padded.
         */
        val `code`: kotlin.String, 
        /**
         * When this pairing attempt gives up.
         */
        val `expiresUnixSecs`: kotlin.Long) : PairingState()
        
    {
        

        companion object
    }
    
    /**
     * The Mac is showing a QR code, and nobody has scanned it yet. QR
     * method.
     */
    data class Offering(
        /**
         * What to draw. `offer.expires_unix_secs` is this state's deadline.
         */
        val `offer`: uniffi.ferry_runtime.PairingOffer) : PairingState()
        
    {
        

        companion object
    }
    
    /**
     * The Mac read a scan's hello and is waiting for `confirm_pairing`. QR
     * method. The phone never shows this: it asks no question of its own.
     */
    data class Requested(
        /**
         * The scanning phone's name, from its hello.
         */
        val `name`: kotlin.String, 
        /**
         * The scanning device's kind, from its hello. Shown as the
         * device's own icon, rather than assuming every scan is a phone.
         */
        val `kind`: uniffi.ferry_runtime.DeviceKind, 
        /**
         * How the phone reached this Mac. Always `Wifi`: QR pairing only
         * dials the Wi-Fi addresses in the offer.
         */
        val `transport`: uniffi.ferry_runtime.Transport) : PairingState()
        
    {
        

        companion object
    }
    
    /**
     * Both sides confirmed. The device is now in `devices()`.
     */
    data class Confirmed(
        /**
         * The new device.
         */
        val `device`: uniffi.ferry_runtime.DeviceInfo) : PairingState()
        
    {
        

        companion object
    }
    
    /**
     * Pairing stopped.
     */
    data class Failed(
        /**
         * Why.
         */
        val `error`: uniffi.ferry_runtime.FerryException) : PairingState()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePairingState : FfiConverterRustBuffer<PairingState>{
    override fun read(buf: ByteBuffer): PairingState {
        return when(buf.getInt()) {
            1 -> PairingState.Idle
            2 -> PairingState.Waiting(
                FfiConverterLong.read(buf),
                )
            3 -> PairingState.Found(
                FfiConverterSequenceTypePairingCandidate.read(buf),
                FfiConverterLong.read(buf),
                )
            4 -> PairingState.Code(
                FfiConverterString.read(buf),
                FfiConverterLong.read(buf),
                )
            5 -> PairingState.Offering(
                FfiConverterTypePairingOffer.read(buf),
                )
            6 -> PairingState.Requested(
                FfiConverterString.read(buf),
                FfiConverterTypeDeviceKind.read(buf),
                FfiConverterTypeTransport.read(buf),
                )
            7 -> PairingState.Confirmed(
                FfiConverterTypeDeviceInfo.read(buf),
                )
            8 -> PairingState.Failed(
                FfiConverterTypeFerryError.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PairingState): ULong = when(value) {
        is PairingState.Idle -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is PairingState.Waiting -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterLong.allocationSize(value.`expiresUnixSecs`)
            )
        }
        is PairingState.Found -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypePairingCandidate.allocationSize(value.`candidates`)
                + FfiConverterLong.allocationSize(value.`expiresUnixSecs`)
            )
        }
        is PairingState.Code -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterLong.allocationSize(value.`expiresUnixSecs`)
            )
        }
        is PairingState.Offering -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePairingOffer.allocationSize(value.`offer`)
            )
        }
        is PairingState.Requested -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterTypeDeviceKind.allocationSize(value.`kind`)
                + FfiConverterTypeTransport.allocationSize(value.`transport`)
            )
        }
        is PairingState.Confirmed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeDeviceInfo.allocationSize(value.`device`)
            )
        }
        is PairingState.Failed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFerryError.allocationSize(value.`error`)
            )
        }
    }

    override fun write(value: PairingState, buf: ByteBuffer) {
        when(value) {
            is PairingState.Idle -> {
                buf.putInt(1)
                Unit
            }
            is PairingState.Waiting -> {
                buf.putInt(2)
                FfiConverterLong.write(value.`expiresUnixSecs`, buf)
                Unit
            }
            is PairingState.Found -> {
                buf.putInt(3)
                FfiConverterSequenceTypePairingCandidate.write(value.`candidates`, buf)
                FfiConverterLong.write(value.`expiresUnixSecs`, buf)
                Unit
            }
            is PairingState.Code -> {
                buf.putInt(4)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterLong.write(value.`expiresUnixSecs`, buf)
                Unit
            }
            is PairingState.Offering -> {
                buf.putInt(5)
                FfiConverterTypePairingOffer.write(value.`offer`, buf)
                Unit
            }
            is PairingState.Requested -> {
                buf.putInt(6)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterTypeDeviceKind.write(value.`kind`, buf)
                FfiConverterTypeTransport.write(value.`transport`, buf)
                Unit
            }
            is PairingState.Confirmed -> {
                buf.putInt(7)
                FfiConverterTypeDeviceInfo.write(value.`device`, buf)
                Unit
            }
            is PairingState.Failed -> {
                buf.putInt(8)
                FfiConverterTypeFerryError.write(value.`error`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Where a transfer is.
 */

enum class TransferState {
    
    /**
     * Waiting for a thread or for the device to be reachable.
     */
    QUEUED,
    /**
     * Moving bytes.
     */
    ACTIVE,
    /**
     * The link dropped. Resumes on its own when the device is reachable.
     */
    PAUSED,
    /**
     * Every chunk verified and the file is at its final name.
     */
    DONE,
    /**
     * Stopped for a reason in `error`. A retry starts from the resume point.
     */
    FAILED;

    


    companion object
}


